"""Demo: the two-point indiscrete space is non-metrizable yet has phantom number 2."""
from __future__ import annotations
from itertools import chain, combinations
from typing import Callable, FrozenSet, Iterable, List

def powerset(elems: Iterable[str]) -> List[FrozenSet[str]]:
    xs = list(elems)
    return [frozenset(c) for c in chain.from_iterable(
        combinations(xs, r) for r in range(len(xs) + 1))]

def topo(ground: Iterable[str], pred: Callable[[FrozenSet[str]], bool]):
    return frozenset(U for U in powerset(ground) if pred(U))

def is_T0(ground, tau) -> bool:
    pts = list(ground)
    for i in range(len(pts)):
        for j in range(i + 1, len(pts)):
            if not any((pts[i] in U) != (pts[j] in U) for U in tau):
                return False
    return True

def main() -> None:
    T, F = "true", "false"
    ground = frozenset({T, F})
    s_true = topo(ground, lambda U: (F not in U) or (T in U))   # opens {}, {true}, X
    s_false = topo(ground, lambda U: (T not in U) or (F in U))  # opens {}, {false}, X
    indiscrete = frozenset({frozenset(), ground})
    consensus = s_true & s_false                                # sets open in BOTH
    assert consensus == indiscrete
    assert indiscrete < s_true and indiscrete < s_false        # each strictly finer
    assert not is_T0(ground, indiscrete)                       # => non-metrizable
    print("consensus == indiscrete:", consensus == indiscrete)
    print("T0 (hence metrizable)?  ", is_T0(ground, indiscrete))
    print("phantom number 2 on a non-metrizable space: conjecture refuted.")

if __name__ == "__main__":
    main()

